function validate([ranks, suits]) {
  if (ranks.length !== 5 || suits.length !== 5) return 'There must be exactly 5 ranks and 5 suits.';
  if (ranks.some(r => !Number.isInteger(r) || r < 1 || r > 13)) return 'Each rank is an integer from 1 to 13.';
  if (suits.some(s => !['a', 'b', 'c', 'd'].includes(s))) return "Each suit is one of 'a', 'b', 'c', 'd'.";
  if (new Set(ranks.map((r, i) => r + suits[i])).size !== 5) return 'No two cards may share both rank and suit.';
  return null;
}

