function bestHand(ranks, suits) {
  const suitCount = new Map();
  for (const suit of suits) {
    suitCount.set(suit, (suitCount.get(suit) ?? 0) + 1);
  }
  if (suitCount.size === 1) {
    return "Flush";
  }

  const rankCount = new Array(14).fill(0);
  let most = 0;
  for (const rank of ranks) {
    rankCount[rank]++;
    most = Math.max(most, rankCount[rank]);
  }

  if (most >= 3) {
    return "Three of a Kind";
  }
  if (most === 2) {
    return "Pair";
  }
  return "High Card";
}

