function bestHand(ranks, suits) {
  if (suits.every(suit => suit === suits[0])) return "Flush";
  for (let i = 0; i < 5; i++)
    for (let j = i + 1; j < 5; j++)
      for (let k = j + 1; k < 5; k++)
        if (ranks[i] === ranks[j] && ranks[j] === ranks[k]) return "Three of a Kind";
  for (let i = 0; i < 5; i++)
    for (let j = i + 1; j < 5; j++)
      if (ranks[i] === ranks[j]) return "Pair";
  return "High Card";
}

