function generate(rand, size) {
  const letters = ['a', 'b', 'c', 'd'];
  if (rand() < 0.25) {
    // A flush: one suit and five different ranks.
    const suit = letters[Math.floor(rand() * 4)];
    const used = new Set();
    while (used.size < 5) used.add(1 + Math.floor(rand() * 13));
    return [[...used], Array(5).fill(suit)];
  }
  // Drawing from only a few ranks makes pairs and triples common.
  const pool = 2 + Math.floor(rand() * 12);
  const firstRank = 1 + Math.floor(rand() * (14 - pool));
  const seen = new Set();
  const ranks = [];
  const suits = [];
  while (ranks.length < 5) {
    const rank = firstRank + Math.floor(rand() * pool);
    const suit = letters[Math.floor(rand() * 4)];
    if (seen.has(rank + suit)) continue;
    seen.add(rank + suit);
    ranks.push(rank);
    suits.push(suit);
  }
  return [ranks, suits];
}
